from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    cells = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value != background]
    if not cells:
        return out
    top = min(r for r, c in cells)
    bottom = max(r for r, c in cells)
    left = min(c for r, c in cells)
    right = max(c for r, c in cells)
    for c in range(left, right + 1):
        if out[top][c] == background:
            out[top][c] = 2
        if out[bottom][c] == background:
            out[bottom][c] = 2
    for r in range(top, bottom + 1):
        if out[r][left] == background:
            out[r][left] = 2
        if out[r][right] == background:
            out[r][right] = 2
        if any(grid[r][c] != background for c in range(left + 1, right)):
            for c in range(left, right + 1):
                if out[r][c] == background:
                    out[r][c] = 2
    return out
